import{_ as a,o as r,c as t,a0 as o}from"./chunks/framework.BPYRhTv9.js";const p=JSON.parse('{"title":"Refund Policy","description":"","frontmatter":{"title":"Refund Policy"},"headers":[],"relativePath":"legal/refund.md","filePath":"legal/refund.md"}'),i={name:"legal/refund.md"};function n(s,e,l,u,c,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="refund-policy" tabindex="-1">Refund Policy <a class="header-anchor" href="#refund-policy" aria-label="Permalink to &quot;Refund Policy&quot;">​</a></h1><p><em>Last updated: Jul 17, 2026</em></p><h3 id="no-refunds" tabindex="-1">No Refunds <a class="header-anchor" href="#no-refunds" aria-label="Permalink to &quot;No Refunds&quot;">​</a></h3><p>All purchases are <strong>final and non-refundable</strong>. Because Buy Me a Coffee is a tipping platform, there is no refund mechanism available. By purchasing a Pro key, you acknowledge that this transaction is a voluntary tip in exchange for a digital thank-you item.</p><h3 id="technical-support" tabindex="-1">Technical Support <a class="header-anchor" href="#technical-support" aria-label="Permalink to &quot;Technical Support&quot;">​</a></h3><p>If your Pro key does not activate after purchase, email <a href="mailto:yellowgreenlabs@proton.me?subject=Pro%20Key%20Issue" target="_blank" rel="noreferrer">yellowgreenlabs@proton.me</a> with the email address you used on Buy Me a Coffee. We will help resolve the issue. This is technical support, not a refund. No money will be returned.</p><h3 id="what-you-are-purchasing" tabindex="-1">What You Are Purchasing <a class="header-anchor" href="#what-you-are-purchasing" aria-label="Permalink to &quot;What You Are Purchasing&quot;">​</a></h3><p>A Pro key is a one-time purchase that unlocks additional features in Wibe Stories, including:</p><ul><li>Up to 50 recordings per day (free tier: 5)</li><li>Up to 30 seconds per recording (free tier: 15)</li><li>Unlimited tone rewrites (free tier: 1 per tone per day)</li><li>Cloud vault with up to 50 saved cards (free tier: localStorage only)</li><li>Bypass the daily 99-user capacity pool</li></ul><p>The Pro key is a text string tied to your email. You receive it once and activate it in the app. It is not a subscription. There are no recurring charges.</p><h3 id="how-payment-works" tabindex="-1">How Payment Works <a class="header-anchor" href="#how-payment-works" aria-label="Permalink to &quot;How Payment Works&quot;">​</a></h3><p>Pro keys are purchased through <a href="https://buymeacoffee.com/" target="_blank" rel="noreferrer">Buy Me a Coffee</a>, a tipping platform. When you buy a Pro key, you are buying a &quot;coffee&quot; (a voluntary tip to the creator) and receiving the Pro key as a thank-you. Buy Me a Coffee does not process refunds on tips.</p><h3 id="service-continuity" tabindex="-1">Service Continuity <a class="header-anchor" href="#service-continuity" aria-label="Permalink to &quot;Service Continuity&quot;">​</a></h3><p>If Wibe Stories is discontinued or the Pro tier is substantially changed, your Pro key may stop unlocking the features described above. You acknowledge this risk at the time of purchase. No refunds will be issued for service changes or discontinuation.</p><h3 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h3><p>For questions about this policy, email <a href="mailto:yellowgreenlabs@proton.me?subject=Refund%20Question" target="_blank" rel="noreferrer">yellowgreenlabs@proton.me</a>.</p>',16)])])}const f=a(i,[["render",n]]);export{p as __pageData,f as default};
